export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds = {}
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const thresholdResults = [];
  let allPassed = true;

  for (const [metricId, minValue] of Object.entries(thresholds)) {
    const metric = evaluations.find(e => e.id === metricId);
    const score = metric?.score;
    const passed = score !== null && score !== undefined && score >= minValue;
    if (!passed) allPassed = false;
    thresholdResults.push({
      metric: metricId,
      min: minValue,
      score: score,
      passed
    });
  }

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (Object.keys(thresholds).length > 0) {
    report.passed = allPassed;
    report.thresholds = thresholdResults;
  }

  return report;
}

