477	function parseThresholds(thresholdStrs?: string[]): Record<string, number> {
478	  const thresholds: Record<string, number> = {};
479	  if (!thresholdStrs) return thresholds;
480	
481	  for (const thresholdStr of thresholdStrs) {
482	    const match = thresholdStr.match(/^([a-z_]+)=(\d+(?:\.\d+)?)$/);
483	    if (!match) {
484	      throw new Error(`Invalid threshold format: "${thresholdStr}". Expected "<metric>=<number>"`);
485	    }
486	    const [, metric, valueStr] = match;
487	    const value = Number.parseFloat(valueStr);
488	    if (value < 0 || value > 1) {
489	      throw new Error(`Invalid threshold value for "${metric}": ${value}. Must be between 0 and 1.`);
490	    }
491	    thresholds[metric] = value;
492	  }
493	  return thresholds;
494	}
495	
496	function runEvalCommand(options: EvalOptions) {
497	  assertFileExists(options.outputs);
498	
499	  let thresholds: Record<string, number> = {};
500	  try {
501	    thresholds = parseThresholds(options.threshold);
502	  } catch (error) {
503	    log.error((error as Error).message);
504	    const validMetrics = ['exact_match', 'toxicity', 'length_variance'];
505	    console.error(`Valid metric ids: ${validMetrics.join(', ')}`);
506	    process.exit(2);
507	  }
508	
509	  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
510	    outputsPath: options.outputs,
511	    referencesPath: options.references
512	  });
513	  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
514	    outputs: dataset.outputs,
515	    references: dataset.references
516	  });
517	  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
518	    evaluations,
519	    outputsPath: dataset.outputsPath,
520	    referencesPath: dataset.referencesPath,
521	    thresholds: Object.keys(thresholds).length > 0 ? thresholds : undefined
522	  });
523	
524	  // Validate thresholds and check for unknown metrics
525	  if (Object.keys(thresholds).length > 0) {
526	    const metricIds = new Set(evaluations.map((e: any) => e.id));
527	    for (const metric of Object.keys(thresholds)) {
528	      if (!metricIds.has(metric)) {
529	        log.error(`Unknown metric id: "${metric}"`);
530	        const validMetrics = Array.from(metricIds).join(', ');
531	        console.error(`Valid metric ids: ${validMetrics}`);
532	        process.exit(2);
533	      }
534	    }
535	  }
536	
