function parseThresholds(thresholdStrs?: string[]): Record<string, number> {
  const thresholds: Record<string, number> = {};
  if (!thresholdStrs) return thresholds;

  for (const thresholdStr of thresholdStrs) {
    const match = thresholdStr.match(/^([a-z_]+)=(\d+(?:\.\d+)?)$/);
    if (!match) {
      throw new Error(`Invalid threshold format: "${thresholdStr}". Expected "<metric>=<number>"`);
    }
    const [, metric, valueStr] = match;
    const value = Number.parseFloat(valueStr);
    if (value < 0 || value > 1) {
      throw new Error(`Invalid threshold value for "${metric}": ${value}. Must be between 0 and 1.`);
    }
    thresholds[metric] = value;
  }
  return thresholds;
}

function runEvalCommand(options: EvalOptions) {
  assertFileExists(options.outputs);

  let thresholds: Record<string, number> = {};
  try {
    thresholds = parseThresholds(options.threshold);
  } catch (error) {
    log.error((error as Error).message);
    const validMetrics = ['exact_match', 'toxicity', 'length_variance'];
    console.error(`Valid metric ids: ${validMetrics.join(', ')}`);
    process.exit(2);
  }

  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });
  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds: Object.keys(thresholds).length > 0 ? thresholds : undefined
  });

  // Validate thresholds and check for unknown metrics
  if (Object.keys(thresholds).length > 0) {
    const metricIds = new Set(evaluations.map((e: any) => e.id));
    for (const metric of Object.keys(thresholds)) {
      if (!metricIds.has(metric)) {
        log.error(`Unknown metric id: "${metric}"`);
        const validMetrics = Array.from(metricIds).join(', ');
        console.error(`Valid metric ids: ${validMetrics}`);
        process.exit(2);
      }
    }
  }

  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
    report,
    format: options.format ?? 'json',
    reportPath: options.report
  });
  log.success('Evaluation report generated.', { path: resolvedPath });

  // Exit with appropriate code based on thresholds
  if ((report as any).passed === false) {
    process.exit(1);
  }
}

